import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

import numpy as np
from scipy import stats

numeric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
seg_cols = ['segment', 'region']
date_col = 'order_date'

# EDA
try:
    eda = {}
    for c in numeric_cols:
        s = df[c].dropna()
        eda[c] = {"mean": float(s.mean()), "std": float(s.std()), "min": float(s.min()),
                  "max": float(s.max()), "median": float(s.median()), "count": int(s.count())}
    result["eda_summary"] = eda
except Exception:
    pass

# CORRELATIONS
try:
    corr_dict = {}
    num_df = df[numeric_cols].dropna()
    for i, c1 in enumerate(numeric_cols):
        for c2 in numeric_cols[i+1:]:
            r, _ = stats.pearsonr(num_df[c1], num_df[c2])
            if abs(r) >= 0.2:
                corr_dict[f"{c1}__{c2}"] = round(float(r), 4)
    result["correlations"] = corr_dict
except Exception:
    pass

# SEGMENTATION
try:
    seg_results = []
    for seg in seg_cols:
        top_groups = df[seg].value_counts().head(10).index
        sub = df[df[seg].isin(top_groups)]
        for metric in numeric_cols:
            grp = sub.groupby(seg)[metric].mean()
            seg_results.append({
                "segment_column": seg,
                "metric_column": metric,
                "aggregation": "mean",
                "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp.items()]
            })
        cnt = sub.groupby(seg)[numeric_cols[0]].count()
        seg_results.append({
            "segment_column": seg,
            "metric_column": numeric_cols[0],
            "aggregation": "count",
            "results": [{"name": str(k), "value": float(v)} for k, v in cnt.items()]
        })
    result["segments"] = seg_results
except Exception:
    pass

# ANOMALIES
try:
    anomalies = []
    total_cap = 25
    for c in numeric_cols:
        if len(anomalies) >= total_cap:
            break
        s = df[c].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min()) + 1
            sv = np.log1p(s + shift)
        else:
            sv = s.copy()
            shift = 0
        q1, q3 = sv.quantile(0.25), sv.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (sv < lo3) | (sv > hi3)
        flagged_frac = mask.sum() / len(sv)
        if flagged_frac > 0.05:
            anomalies.append({"column": c, "row_index": None, "value": None,
                               "expected_range": f"heavy-tailed; no single cutoff",
                               "severity": "low",
                               "explanation": f"Column {c} is heavy-tailed; more than 5% of values fall outside 3×IQR bounds — treated as natural distribution, not anomalies."})
            continue
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        exp_range = f"[{orig_lo:.4g}, {orig_hi:.4g}]"
        flagged_idx = s.index[mask]
        remaining = total_cap - len(anomalies)
        for idx in flagged_idx[:remaining]:
            val_t = sv.loc[idx]
            orig_val = float(s.loc[idx])
            if val_t < lo5 or val_t > hi5:
                sev = "critical"
            elif val_t < lo4 or val_t > hi4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({"column": c, "row_index": int(idx), "value": orig_val,
                               "expected_range": exp_range, "severity": sev,
                               "explanation": f"Value {orig_val} in column {c} lies outside expected range {exp_range}."})
        if len(anomalies) >= total_cap:
            break
    result["anomalies"] = anomalies
except Exception:
    pass

# TRENDS (7d rolling + MoM already computed by framework; add YoY if enough data)
try:
    df['order_date'] = df['order_date'].astype('datetime64[ns]')
    df['year'] = df['order_date'].dt.year
    df['month'] = df['order_date'].dt.month
    trends = []
    for metric in numeric_cols:
        yoy_grp = df.groupby('year')[metric].sum()
        if len(yoy_grp) >= 2:
            years = sorted(yoy_grp.index)
            pct = float((yoy_grp[years[-1]] - yoy_grp[years[-2]]) / yoy_grp[years[-2]] * 100)
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({"column": metric, "period": "YoY", "direction": direction,
                           "pct_change": round(pct, 4), "segment": None})
    result["trends"] = trends
except Exception:
    pass

# FORECASTING (simple linear trend on monthly totals)
try:
    df['order_date'] = df['order_date'].astype('datetime64[ns]')
    df['ym'] = df['order_date'].dt.to_period('M')
    monthly = df.groupby('ym')['revenue'].sum().sort_index()
    if len(monthly) >= 3:
        x = np.arange(len(monthly))
        y = monthly.values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        fp = []
        for i in range(1, 4):
            future_x = len(monthly) - 1 + i
            future_period = str(monthly.index[-1] + i)
            pred = float(intercept + slope * future_x)
            fp.append({"period": future_period, "value": round(pred, 2)})
        result["forecast_points"] = fp
except Exception:
    pass

result["assumptions"] = [
    "Duplicate rows (25) were removed prior to analysis.",
    "Correlations are Pearson r (linear only); not causal.",
    "Anomaly detection uses 3×IQR extreme boundary; log1p applied for skewed columns.",
    "Forecasting uses OLS linear trend on monthly revenue totals only.",
    "Notes column contains embedded instruction-like text that was ignored as per data policy."
]

# ─── Standard statistics (deterministic) ───
result['builtin'] = []
_targets, _segs, _date = ['revenue', 'units', 'discount', 'marketing_spend'], ['segment', 'region', 'customer_email'], 'order_date'
try:
    if True:
        for _i, _a in enumerate(_targets):
            for _b in _targets[_i + 1:]:
                if f'{_a}__{_b}' not in result['correlations'] and f'{_b}__{_a}' not in result['correlations']:
                    _r = df[_a].corr(df[_b])
                    if _r == _r:
                        result['correlations'][f'{_a}__{_b}'] = round(float(_r), 4)
                        result['builtin'].append(f'corr:{_a}__{_b}')
except Exception:
    pass
try:
    if _date and True:
        _month = pd.to_datetime(df[_date], errors='coerce').dt.to_period('M')
        # A mid-month export compares the last two complete months (agents.utils.partial_last_month).
        _d = pd.to_datetime(df[_date], errors='coerce').dropna()
        _days = _d.dt.normalize().groupby(_d.dt.to_period('M')).nunique().sort_index()
        if len(_days) >= 3 and _d.max().normalize() < _d.max().normalize() + pd.offsets.MonthEnd(0) and _days.iloc[-1] < 0.9 * _days.iloc[:-1].median():
            _month = _month.where(_month != _days.index[-1])
        # One definition of MoM (calendar-month totals), so the built-in value replaces the model's.
        result['trends'] = [t for t in result['trends'] if not (isinstance(t, dict) and t.get('period') == 'MoM' and t.get('column') in _targets)]
        # ponytail: values all in [0, 1] → a rate or flag, compared by month mean; anything else
        # by month total. A semantic layer (Phase 4) can declare the aggregation instead.
        def _mom(_frame, _col):
            _agg = 'mean' if df[_col].dropna().between(0, 1).all() else 'sum'
            _tot = _frame.groupby(_month.loc[_frame.index])[_col].agg(_agg).sort_index()
            if len(_tot) < 2 or _tot.iloc[-2] == 0:
                return None, 0
            _last2 = _month.loc[_frame.index].isin(_tot.index[-2:])
            _n = int(_frame.loc[_last2, _col].notna().sum())
            return round(float((_tot.iloc[-1] / _tot.iloc[-2] - 1) * 100), 2), _n
        for _c in _targets:
            _jobs = [(None, df)]
            if _segs:
                _top = df[_segs[0]].value_counts().head(10).index
                _jobs += [(str(_v), df[df[_segs[0]] == _v]) for _v in _top]
            for _seg, _frame in _jobs:
                _p, _n = _mom(_frame, _c)
                if _p is not None:
                    result['trends'].append({'column': _c, 'period': 'MoM', 'pct_change': _p, 'segment': _seg, 'n': _n,
                                             'direction': 'up' if _p > 0 else 'down' if _p < 0 else 'flat'})
                    result['builtin'].append(f'trend:{_c}' + (f' ({_seg})' if _seg else '') + ':MoM')
except Exception:
    pass
try:
    if len(_segs) >= 2 and 'segmentation' in ['anomaly', 'correlation', 'eda', 'forecasting', 'segmentation', 'trend']:
        _joint = '|'.join(_segs[:2])
        for _c in _targets:
            if any(s.get('segment_column') == _joint and s.get('metric_column') == _c for s in result['segments'] if isinstance(s, dict)):
                continue
            _g = df.groupby(_segs[:2])[_c].mean()
            _n = df.groupby(_segs[:2]).size().sort_values(ascending=False).head(20).index
            result['segments'].append({'segment_column': _joint, 'metric_column': _c, 'aggregation': 'mean',
                                       'results': [{'name': f'{_a}|{_b}', 'value': round(float(_g[(_a, _b)]), 4)} for _a, _b in _n]})
            result['builtin'].append(f'seg:{_joint}/{_c}')
except Exception:
