import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    metrics = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in metrics:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

try:
    seg_cols = ['segment', 'region']
    for sc in seg_cols:
        for mc in metrics:
            top = df[sc].value_counts().head(10).index
            sub = df[df[sc].isin(top)]
            for agg, agg_name in [('mean', 'mean'), ('sum', 'sum'), ('count', 'count')]:
                res_list = []
                for grp, gdf in sub.groupby(sc):
                    if agg == 'mean':
                        val = float(gdf[mc].mean())
                    elif agg == 'sum':
                        val = float(gdf[mc].sum())
                    else:
                        val = float(gdf[mc].count())
                    res_list.append({'name': str(grp), 'value': val})
                result['segments'].append({
                    'segment_column': sc, 'metric_column': mc,
                    'aggregation': agg_name, 'results': res_list
                })
    sc1, sc2 = 'segment', 'region'
    for mc in metrics:
        top1 = df[sc1].value_counts().head(5).index
        top2 = df[sc2].value_counts().head(5).index
        sub = df[df[sc1].isin(top1) & df[sc2].isin(top2)]
        res_list = []
        for (g1, g2), gdf in sub.groupby([sc1, sc2]):
            res_list.append({'name': f'{g1}|{g2}', 'value': float(gdf[mc].mean())})
        result['segments'].append({
            'segment_column': f'{sc1}|{sc2}', 'metric_column': mc,
            'aggregation': 'mean', 'results': res_list
        })
except Exception:
    pass

try:
    import numpy as np
    num_df = df[metrics].dropna()
    corr = num_df.corr(method='pearson')
    for i, c1 in enumerate(metrics):
        for j, c2 in enumerate(metrics):
            if j <= i:
                continue
            r = float(corr.loc[c1, c2])
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(r, 4)
except Exception:
    pass

try:
    import numpy as np
    from scipy import stats as sp_stats
    skip_cols = {'order_id'}
    anomaly_records = []
    for col in metrics:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -float(s.min()) + 1 if float(s.min()) < 0 else 0
            xs = np.log1p(s + shift)
        else:
            xs = s.copy()
            shift = 0
        q1, q3 = float(xs.quantile(0.25)), float(xs.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (xs < lo3) | (xs > hi3)
        frac = mask.sum() / len(xs)
        if frac > 0.05:
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else lo3
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else hi3
            anomaly_records.append({
                'column': col, 'row_index': None,
                'value': f'{frac:.1%} of values',
                'expected_range': f'[{orig_lo:.2f}, {orig_hi:.2f}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; {frac:.1%} of values fall outside expected_range — column skipped for individual flagging'
            })
            continue
        col_records = []
        for idx in xs[mask].index:
            xv = float(xs[idx])
            orig_v = float(s[idx])
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else lo3
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else hi3
            if xv > hi5 or xv < lo5:
                sev = 'critical'
            elif xv > hi4 or xv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            col_records.append({
                'column': col, 'row_index': int(idx),
                'value': orig_v,
                'expected_range': f'[{orig_lo:.2f}, {orig_hi:.2f}]',
                'severity': sev,
                'explanation': f'{col} value {orig_v} lies outside expected_range [{orig_lo:.2f}, {orig_hi:.2f}]'
            })
        anomaly_records.extend(col_records)
    anomaly_records = anomaly_records[:25]
    result['anomalies'] = anomaly_records
except Exception:
    pass

try:
    import numpy as np
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['_ym'] = df['order_date'].dt.to_period('M')
    for col in metrics:
        monthly = df.groupby('_ym')[col].mean().sort_index()
        if len(monthly) < 2:
            continue
        pct = float((monthly.iloc[-1] - monthly.iloc[-2]) / monthly.iloc[-2] * 100) if monthly.iloc[-2] != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': col, 'period': 'MoM', 'direction': direction,
            'pct_change': round(pct, 4), 'segment': None
        })
    roll_col = 'revenue'
    df_sorted = df.sort_values('order_date')
    df_sorted['_roll7'] = df_sorted[roll_col].rolling(7).mean()
    last_val = float(df_sorted['_roll7'].dropna().iloc[-1])
    prev_val = float(df_sorted['_roll7'].dropna().iloc[-8]) if len(df_sorted['_roll7'].dropna()) > 8 else float(df_sorted['_roll7'].dropna().iloc[0])
    pct7 = float((last_val - prev_val) / prev_val * 100) if prev_val != 0 else 0.0
    dir7 = 'up' if pct7 > 1 else ('down' if pct7 < -1 else 'flat')
    result['trends'].append({
        'column': roll_col, 'period': '7d_rolling', 'direction': dir7,
        'pct_change': round(pct7, 4), 'segment': None
    })
except Exception:
    pass

try:
    import numpy as np
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['_ym'] = df['order_date'].dt.to_period('M')
    monthly_rev = df.groupby('_ym')['revenue'].mean().sort_index()
    if len(monthly_rev) >= 3:
        x = np.arange(len(monthly_rev))
        y = monthly_rev.values
        coeffs = np.polyfit(x, y, 1)
        next_periods = [len(monthly_rev), len(monthly_rev) + 1]
        for np_i in next_periods:
            pred = float(np.polyval(coeffs, np_i))
            period_label = str((monthly_rev.index[-1] + (np_i - len(monthly_rev) + 1)).strftime('%Y-%m'))
            result['forecast_points'].append({'period': period_label, 'value': round(pred, 4)})
except Exception:
