    import numpy as np
    from scipy import stats as sp_stats
    skip_cols = {'order_id'}
    anomaly_records = []
    for col in metrics:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -float(s.min()) + 1 if float(s.min()) < 0 else 0
            xs = np.log1p(s + shift)
        else:
            xs = s.copy()
            shift = 0
        q1, q3 = float(xs.quantile(0.25)), float(xs.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (xs < lo3) | (xs > hi3)
        frac = mask.sum() / len(xs)
        if frac > 0.05:
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else lo3
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else hi3
            anomaly_records.append({
                'column': col, 'row_index': None,
                'value': f'{frac:.1%} of values',
                'expected_range': f'[{orig_lo:.2f}, {orig_hi:.2f}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; {frac:.1%} of values fall outside expected_range — column skipped for individual flagging'
            })
            continue
        col_records = []
        for idx in xs[mask].index:
            xv = float(xs[idx])
            orig_v = float(s[idx])
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else lo3
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else hi3
            if xv > hi5 or xv < lo5:
                sev = 'critical'
            elif xv > hi4 or xv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            col_records.append({
                'column': col, 'row_index': int(idx),
                'value': orig_v,
                'expected_range': f'[{orig_lo:.2f}, {orig_hi:.2f}]',
                'severity': sev,
                'explanation': f'{col} value {orig_v} lies outside expected_range [{orig_lo:.2f}, {orig_hi:.2f}]'
            })
        anomaly_records.extend(col_records)
    anomaly_records = anomaly_records[:25]
    result['anomalies'] = anomaly_records
except Exception:
    pass

