            xs = np.log1p(s + shift)
        else:
            xs = s.copy()
            shift = 0
        q1, q3 = float(xs.quantile(0.25)), float(xs.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (xs < lo3) | (xs > hi3)
        frac = mask.sum() / len(xs)
        if frac > 0.05:
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else lo3
