try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    all_anomalies = []
    for col in anomaly_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_t < lo3) | (s_t > hi3)
        flagged_frac = mask.sum() / len(s)
        if flagged_frac > 0.05:
            all_anomalies.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'Column {col} has heavy-tailed distribution; more than 5% of values fall outside 3×IQR bounds — not flagged individually.'
            })
            continue
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        exp_range = f'[{orig_lo:.3g}, {orig_hi:.3g}]'
        flagged_idx = s_t[mask].index
        for idx in flagged_idx:
            val = float(df.loc[idx, col])
            t_val = s_t.loc[idx]
            if t_val > hi5 or t_val < lo5:
                sev = 'critical'
            elif t_val > hi4 or t_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            all_anomalies.append({
                'column': col, 'row_index': int(idx), 'value': val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'Value {val} in column {col} lies outside expected range {exp_range}.'
            })
    all_anomalies_sorted = sorted(
        [a for a in all_anomalies if a['row_index'] is not None],
        key=lambda x: {'critical':0,'high':1,'medium':2,'low':3}[x['severity']]
    ) + [a for a in all_anomalies if a['row_index'] is None]
    result['anomalies'] = all_anomalies_sorted[:25]
except Exception:
    pass

