try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_records = []
    skip_cols = ['order_id']
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(np.expm1(lo3) - shift):.2f}, {float(np.expm1(hi3) - shift):.2f}]' if abs(skew) > 2 else f'[{float(lo3):.2f}, {float(hi3):.2f}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; {frac:.1%} of values exceed the 3×IQR boundary — column not individually flagged'
            })
            continue
        flagged = s_t[mask]
        for idx in flagged.index[:25]:
            raw_val = float(df.loc[idx, col])
            t_val = float(s_t[idx])
            if t_val > hi5 or t_val < lo5:
                sev = 'critical'
            elif t_val > hi4 or t_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo3) - shift)
                hi_orig = float(np.expm1(hi3) - shift)
            else:
                lo_orig = float(lo3)
                hi_orig = float(hi3)
            exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range,
                'severity': sev,
                'explanation': f'{col} value {raw_val} lies outside expected range {exp_range}'
            })
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

