import numpy as np
from scipy import stats

# EDA
try:
    metric_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in metric_cols:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# CORRELATIONS
try:
    num_df = df[metric_cols].dropna()
    for i, c1 in enumerate(metric_cols):
        for c2 in metric_cols[i+1:]:
            r, _ = stats.pearsonr(num_df[c1], num_df[c2])
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# SEGMENTATION
try:
    seg_cols = ['segment', 'region']
    agg_map = {'revenue': 'mean', 'units': 'mean', 'discount': 'mean', 'marketing_spend': 'mean'}
    for seg in seg_cols:
        for metric in metric_cols:
            grp = df.groupby(seg)[metric].mean()
            top = grp.nlargest(10)
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'mean',
                'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in top.items()]
            })
    # count per segment
    for seg in seg_cols:
        grp = df.groupby(seg)['order_id'].count()
        result['segments'].append({
            'segment_column': seg, 'metric_column': 'order_id',
            'aggregation': 'count',
            'results': [{'name': str(k), 'value': float(v)} for k, v in grp.items()]
        })
    # two-column breakdown segment|region for revenue
    two_grp = df.groupby(['segment', 'region'])['revenue'].mean()
    result['segments'].append({
        'segment_column': 'segment|region', 'metric_column': 'revenue',
        'aggregation': 'mean',
        'results': [{'name': f'{k[0]}|{k[1]}', 'value': round(float(v), 4)} for k, v in two_grp.items()]
    })
except Exception:
    pass

# ANOMALIES
try:
    anomaly_records = []
    total_cap = 25
    for col in metric_cols:
        if total_cap <= 0:
            break
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min()) + 1
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo3, hi3 = Q1 - 3*IQR, Q3 + 3*IQR
        lo4, hi4 = Q1 - 4*IQR, Q3 + 4*IQR
        lo5, hi5 = Q1 - 5*IQR, Q3 + 5*IQR
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.quantile(0.25)):.4g}, {float(s.quantile(0.75)):.4g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        flagged_idx = s_t[mask].index
        col_lo_orig = float(np.expm1(lo3) - shift) if abs(skew) > 2 else float(lo3)
        col_hi_orig = float(np.expm1(hi3) - shift) if abs(skew) > 2 else float(hi3)
        exp_range = f'[{col_lo_orig:.4g}, {col_hi_orig:.4g}]'
        for idx in flagged_idx:
            if total_cap <= 0:
                break
            val = float(df.loc[idx, col])
            tv = float(s_t[idx])
            if tv > hi5 or tv < lo5:
                sev = 'critical'
            elif tv > hi4 or tv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val:.4g} lies outside expected range {exp_range}'
            })
            total_cap -= 1
    result['anomalies'] = anomaly_records
except Exception:
    pass

# TRENDS (7d rolling)
try:
    df['order_date'] = pd.to_datetime(df['order_date'])
    daily = df.groupby('order_date')[metric_cols].mean().sort_index()
    rolling = daily.rolling(7).mean()
    for col in metric_cols:
        valid = rolling[col].dropna()
        if len(valid) < 2:
            continue
        first_half = valid.iloc[:len(valid)//2].mean()
        second_half = valid.iloc[len(valid)//2:].mean()
        pct = float((second_half - first_half) / first_half * 100) if first_half != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': col, 'period': '7d_rolling', 'direction': direction,
            'pct_change': round(pct, 4), 'segment': None
        })
except Exception:
    pass

# FORECASTING (simple linear extrapolation, next 3 months)
try:
    df['order_date'] = pd.to_datetime(df['order_date'])
    monthly = df.groupby(df['order_date'].dt.to_period('M'))['revenue'].sum().reset_index()
    monthly.columns = ['period', 'revenue']
    monthly['t'] = np.arange(len(monthly))
    if len(monthly) >= 3:
        slope, intercept, _, _, _ = stats.linregress(monthly['t'], monthly['revenue'])
        last_t = monthly['t'].max()
        last_period = monthly['period'].max()
        fps = []
        for i in range(1, 4):
            pred_val = float(intercept + slope * (last_t + i))
            pred_period = str(last_period + i)
            fps.append({'period': pred_period, 'value': round(pred_val, 2)})
        result['forecast_points'] = fps
except Exception:
    pass

# ASSUMPTIONS
result['assumptions'] = [
    'Correlations are Pearson r (linear only); not causal.',
    'Anomaly detection uses Q1-3xIQR / Q3+3xIQR extreme boundaries; log1p applied when |skew|>2.',
    'Forecast uses OLS linear regression on monthly revenue totals; assumes linear trend.',
    '7d rolling trend direction: >1% change = up/down, else flat.',
    'customer_email excluded from segmentation (high cardinality PII); notes column contains embedded instructions that were ignored.'
]

